function AdminView({ orders, loading, onRefresh, onAdvance, onSetPaymentStatus, onViewProof, menu, onToggleSoldOut }) {
  const todayTotal = orders
    .filter((o) => new Date(o.placedAt).toDateString() === new Date().toDateString())
    .reduce((s, o) => s + o.total, 0);

  return (
    <section className="sb-admin">
      <div className="sb-orders-head">
        <h2 className="sb-section-title"><ChefHat size={20} /> Kitchen Dashboard</h2>
        <button className="sb-btn-outline-sm" onClick={onRefresh}>
          <RefreshCw size={13} className={loading ? "sb-spin" : ""} /> Refresh
        </button>
      </div>

      <div className="sb-admin-stats">
        <div className="sb-stat-card">
          <span className="sb-stat-label">Orders today</span>
          <span className="sb-stat-value">{orders.filter((o) => new Date(o.placedAt).toDateString() === new Date().toDateString()).length}</span>
        </div>
        <div className="sb-stat-card">
          <span className="sb-stat-label">Revenue today</span>
          <span className="sb-stat-value">{money(todayTotal)}</span>
        </div>
        <div className="sb-stat-card">
          <span className="sb-stat-label">Awaiting verification</span>
          <span className="sb-stat-value">{orders.filter((o) => o.paymentStatus === "Pending Review").length}</span>
        </div>
      </div>

      <h4 className="sb-admin-subhead">Order Queue</h4>
      <p className="sb-admin-hint">
        Review each customer's details and order first. Check their proof of payment before approving —
        approving moves the order from "Awaiting Verification" to "Order Placed" so the kitchen can start.
      </p>
      {orders.length === 0 ? (
        <div className="sb-empty"><Package size={28} /><p>No orders yet.</p></div>
      ) : (
        <div className="sb-admin-orders">
          {orders.map((o) => (
            <div className="sb-admin-order-card" key={o.id}>
              <div className="sb-admin-order-top">
                <div>
                  <span className="sb-order-id">{o.id}</span>
                  {o.location && <span className="sb-branch-pill"><MapPin size={11} /> {o.location.name}</span>}
                  <span className={`sb-status-pill status-${statusClass(o.status)}`}>{o.status}</span>
                </div>
                <span className="sb-order-total">{money(o.total)}</span>
              </div>

              <div className="sb-admin-order-customer">
                <strong>{o.customer.name}</strong> &middot; WhatsApp: {o.customer.whatsapp} &middot; {o.customer.orderType}
                {o.customer.orderType === "delivery" && ` · ${o.customer.address}`}
              </div>
              <div className="sb-order-items-mini">
                {o.items.map((it) => `${it.qty}× ${it.name}${it.addons.length ? ` (${it.addons.join(", ")})` : ""}`).join(", ")}
              </div>
              {o.customer.notes && <div className="sb-admin-order-notes">Note: {o.customer.notes}</div>}

              <div className="sb-admin-payment-row">
                <span className={`sb-payment-pill payment-${statusClass(o.paymentStatus || "Pending Review")}`}>
                  Payment: {o.paymentStatus || "Pending Review"}
                </span>
                <button className="sb-btn-outline-sm" onClick={() => onViewProof(o.id)}>View proof</button>
              </div>

              <div className="sb-admin-actions">
                {o.paymentStatus !== "Approved" ? (
                  <>
                    <button className="sb-btn-gold-sm" onClick={() => onSetPaymentStatus(o.id, "Approved")}>
                      <Check size={13} /> Approve payment
                    </button>
                    <button className="sb-btn-outline-sm sb-btn-danger" onClick={() => onSetPaymentStatus(o.id, "Rejected")}>
                      Reject
                    </button>
                  </>
                ) : (
                  o.status !== "Completed" && (
                    <button className="sb-btn-outline-sm" onClick={() => onAdvance(o.id)}>
                      Mark as {STATUS_FLOW[STATUS_FLOW.indexOf(o.status) + 1]} <ChevronRight size={13} />
                    </button>
                  )
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      <h4 className="sb-admin-subhead">Menu Availability</h4>
      <div className="sb-admin-menu-list">
        {menu.map((m) => (
          <div className="sb-admin-menu-row" key={m.id}>
            <span>{m.name}</span>
            <button
              className={`sb-toggle ${!m.soldOut ? "on" : ""}`}
              onClick={() => onToggleSoldOut(m.id)}
            >
              {m.soldOut ? "Sold out" : "Available"}
            </button>
          </div>
        ))}
      </div>
    </section>
  );
}

